import{_ as i,a0 as r,w as m,s as l,ao as p,I as o,x as t,a1 as a,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"保护你的文件，请在 Linux 中更改 Umask 值 | LCTT x X-CMD","titleTemplate":false,"description":"保护你的文件，请在 Linux 中更改 Umask 值 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"保护你的文件，请在 Linux 中更改 Umask 值 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"保护你的文件，请在 Linux 中更改 Umask 值 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/How to Change Umask Value Permanently in Linux","title":"保护你的文件，请在 Linux 中更改 Umask 值","tag":"201405","desc":""},"relativePath":"201405/How to Change Umask Value Permanently in Linux.md","filePath":"[post].md"}'),u={name:"201405/How to Change Umask Value Permanently in Linux.md"};function x(d,n,k,L,g,f){const e=r("Link");return m(),l("div",null,[n[11]||(n[11]=p(`<h1 id="保护你的文件-请在-linux-中更改-umask-值" tabindex="-1">保护你的文件，请在 Linux 中更改 Umask 值 <a class="header-anchor" href="#保护你的文件-请在-linux-中更改-umask-值" aria-label="Permalink to “保护你的文件，请在 Linux 中更改 Umask 值”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Change-Umask-Value-Permanently-in-Linux-435026-2.jpg" alt=""></p><p><strong>这篇教程教将指导 Linux 用户如何永久性地更改其系统的 Umask 值。特别建议全新安装的用户学习（想知道为什么的话，请移步下文）</strong></p><p>Umask 是什么？解释下，UMASK 代表用户掩码或用户文件创建掩码，它用于新创建的文件和文件夹，是其默认权限的基础。</p><p>上面的意思可以解释成任何基于 Linux 的操作系统为新建文件(包括文件夹)添加默认权限的规则。出于教育目的，下面列出了一些可以用来设置文件权限的八进制值<strong>掩码</strong>：</p><pre><code>0 – 读, 写, 可执行 (rwx)
1 – 读和写 (rw-)
2 – 读和可执行 (r-x)
3 – 只读 (r--)
4 – 写和可执行 (-wx)
5 – 只写 (-w-)
6 – 仅可执行 (--x)
7 – 没有权限 (---)
</code></pre><p>在几乎所有的 Linux 发行版本中默认 Umask 值是 0022(或022)，可以在终端模拟程序中输入 umask 命令来查看。也可以运行 “umask 八进制值掩码” 命令（例如 umask 027）来临时改变这个值。</p><p>你也许知道，新创建的文件的默认权限设置原本应该是 0666，文件夹的是 0777。应用上面所说的 umask 值后就得到 644 和 755 权限。</p><p>许多意见认为 022 掩码会带来隐私问题，也就是说您所创建的文件对其他用户来说是可随意查看的，一想到这就感到不太爽！</p><p>言归正传，用户可以按他们所愿来修改默认的 Umask 值，当然首先要保证修改的值合法。要修改默认值，<strong>请在您的 shell 配置文件中或者 /etc/profile 文件中写入一个新的 Umask 值</strong>。</p><p>好了，这就大功告成了！从现在开始，在你的 Linux 系统上新创建的文件或文件夹都会有准确设置的权限。但请注意已经存在的文件或文件夹的权限并不会因为上面的操作而改变。</p><p>如果您使用的是命令行，可以在任意目录下运行 ls -lah 命令，就可以看到当前的文件权限。另外，新手也可以很容易地查看到文件权限，在基于 GNOME 桌面的环境中，通过右击文件，选择属性 -&gt; 权限选项卡。</p><p>如果你在阅读这篇教程时遇到任何问题，不要犹豫，请留下您的评论。</p><hr>`,14)),o("p",null,[n[1]||(n[1]=t("via: ",-1)),a(e,{href:"http://news.softpedia.com/news/How-to-Change-Umask-Value-Permanently-in-Linux-435026.shtml"},{default:s(()=>[...n[0]||(n[0]=[t("http://news.softpedia.com/news/How-to-Change-Umask-Value-Permanently-in-Linux-435026.shtml",-1)])]),_:1})]),o("p",null,[n[4]||(n[4]=t("译者：",-1)),a(e,{href:"https://github.com/runningwater"},{default:s(()=>[...n[2]||(n[2]=[t("runningwater",-1)])]),_:1}),n[5]||(n[5]=t(" 校对：",-1)),a(e,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...n[3]||(n[3]=[t("Caroline",-1)])]),_:1})]),o("p",null,[n[8]||(n[8]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原创翻译，",-1)),a(e,{href:"http://linux.cn/"},{default:s(()=>[...n[7]||(n[7]=[t("Linux中国",-1)])]),_:1}),n[10]||(n[10]=t(" 荣誉推出",-1))])])}const U=i(u,[["render",x]]);export{w as __pageData,U as default};
